    "type": "workout",
    "visibility": "private",
    "metadata": {
      "created_at": "2026-06-05T00:00:00Z",
      "created_by": "trainer",
      "difficulty": "beginner",
      "language": "en",
      "estimated_duration_days": 14,
      "tags": [
        "meniscus",
        "rehab_friendly",
        "strength",
        "ski_prep",
        "starter_block"
      ]
    },
    "goals": [
      {
        "id": "primary_strength_return_to_skiing",
        "type": "primary",
        "category": "strength",
        "name": "Build lower-body and core strength for return to skiing",
        "description": "Progress safe strength and control while avoiding deep loaded knee flexion and high-impact activities."
      }
    ],
    "requirements": {
      "min_age": 18,
      "fitness_level": [
        "recreational"
      ],
      "equipment": [
        {
          "id": "barbell",
          "name": "Barbell",
          "required": false,
          "alternatives": [
            "dumbbell",
            "trap_bar"
          ]
        },
        {
          "id": "dumbbells",
          "name": "Dumbbells",
          "required": true
        },
        {
          "id": "machine_leg_press",
          "name": "Leg press machine",
          "required": false
        },
        {
          "id": "cables",
          "name": "Cable machine",
          "required": false
        },
        {
          "id": "bosu",
          "name": "Bosu / balance pad",
          "required": false
        }
