      "inputs": [
        {
          "id": "user.age",
          "type": "number",
          "source": "user.age",
          "label": "Age"
        },
        {
          "id": "user.injuries",
          "type": "array",
          "source": "user.injuries",
          "label": "Injuries"
        }
      ],
      "rules": [
        {
          "id": "no_deep_knee_flexion",
          "condition": {
            "field": "user.injuries",
            "op": "contains",
            "value": "right_medial_meniscus_tear_recovery"
